/**
 * The Retrace document format. Everything here is plain JSON so projects can be
 * saved to disk, diffed, and generated by scripts or AI agents.
 */

import type { BrushStyle } from './brushes';

/** x, y in project pixels; pressure 0..1; t = ms since the stroke started. */
export type Point = [x: number, y: number, pressure: number, t: number];

export interface GradientStop {
  /** 0..1 along the gradient. */
  offset: number;
  color: string;
}

/**
 * A gradient fill for a stroke, laid over the stroke's own bounding box so it moves and
 * scales with the stroke. Linear: angle in degrees (0 = left to right, 90 = top to bottom).
 * Radial: from the center out.
 */
export interface Gradient {
  type: 'linear' | 'radial';
  angle: number;
  stops: GradientStop[];
  /**
   * The area the gradient spans, in project pixels. Strokes that belong together (a word,
   * a shape, a recolored selection) share one box so the colors flow across all of them.
   * Defaults to the stroke's own bounds.
   */
  box?: { x: number; y: number; width: number; height: number };
}

export interface Stroke {
  id: string;
  points: Point[];
  /** Solid color, and the fallback (first stop) when a gradient is set. */
  color: string;
  gradient?: Gradient;
  /** Nib diameter in project pixels. */
  size: number;
  /** Defaults to 'marker'. */
  brush?: BrushStyle;
  /** Mouse/touch/generated input has no real pressure, so derive it from velocity instead. */
  simulatePressure: boolean;
  /**
   * Fill color for the area the stroke encloses (its centerline, closed with a straight
   * edge). Opaque, so it covers whatever is underneath. Appears once the line is finished.
   */
  fill?: string;
  /**
   * Stacking order, independent of when the stroke draws: higher layers paint on top.
   * Strokes on the same layer stack in drawing order. Defaults to 0.
   */
  layer?: number;
}

export interface Step {
  id: string;
  /** Optional human/AI-readable note, e.g. "draw the CPU". */
  label?: string;
  strokes: Stroke[];
  /** The track this step plays on (a track id). Defaults to the main track. */
  track?: string;
  /**
   * Empty time before this step starts, in ms, after the previous step on the same track
   * finishes. Lets a caption wait for the drawing it labels. Defaults to 0.
   */
  delay?: number;
  /** Pause after this step finishes drawing, in ms. */
  hold: number;
  /** Starts a new scene: the canvas is wiped before this step draws. */
  newScene?: boolean;
  /** The scene's name, kept on the scene's first step. */
  sceneName?: string;
  /**
   * Playback speed for this step, multiplied with the project speed. Applies to the pen
   * motion and the pauses between strokes, so captions can be written briskly while
   * drawings keep a natural pace. Defaults to 1.
   */
  speed?: number;
}

/**
 * A row of the timeline. Within a scene, each track plays its own steps one after another,
 * and tracks play side by side, so a caption can be written while a drawing is drawn.
 * Tracks also stack: a later track paints over an earlier one.
 */
export interface Track {
  id: string;
  name: string;
  /** Left out of the canvas, playback and export; its steps keep their time. */
  hidden?: boolean;
  /** Its strokes show but can't be drawn into, selected or erased. */
  locked?: boolean;
}

export interface Project {
  version: 1;
  width: number;
  height: number;
  background: string;
  /** Playback speed multiplier applied to recorded drawing motion. */
  speed: number;
  /** Bottom to top. Absent means one main track, which is how every older project plays. */
  tracks?: Track[];
  /**
   * Grouped by scene: a scene is a run of steps starting at step 0 or a `newScene` step.
   * Within a scene, steps on the same track play in this order.
   */
  steps: Step[];
}

export const MAIN_TRACK: Track = { id: 'main', name: 'Main' };

export function tracksOf(project: Project): Track[] {
  return project.tracks?.length ? project.tracks : [MAIN_TRACK];
}

/** Position of a step's track in the stack (0 = bottom). Unknown tracks fall back to the bottom one. */
export function trackIndex(project: Project, step: Step): number {
  const tracks = tracksOf(project);
  const id = step.track ?? MAIN_TRACK.id;
  return Math.max(0, tracks.findIndex((t) => t.id === id));
}

export function trackOf(project: Project, step: Step): Track {
  return tracksOf(project)[trackIndex(project, step)];
}

/** Stacking key for a stroke: its track first, then its own layer within the track. */
export function strokeZ(track: number, stroke: Stroke): number {
  return track * 1e6 + (stroke.layer ?? 0);
}

/**
 * Items in the order they're painted, bottom to top: by stacking key (see `strokeZ`),
 * then in drawing order. Stable, and returns the input untouched when nothing is stacked.
 */
export function paintOrder<T>(items: T[], zOf: (item: T) => number): T[] {
  if (!items.some((it) => zOf(it))) return items;
  return items
    .map((item, i) => ({ item, i, z: zOf(item) }))
    .sort((a, b) => a.z - b.z || a.i - b.i)
    .map((e) => e.item);
}

/** A step's effective playback rate: project speed times the step's own speed. */
export function stepRate(project: Project, step: Step): number {
  return project.speed * (step.speed && step.speed > 0 ? step.speed : 1);
}

export interface SceneInfo {
  /** 0-based position among the project's scenes. */
  index: number;
  /** First and last step index of the scene. */
  first: number;
  last: number;
  name?: string;
}

/** The project's scenes in order: runs of steps, each starting at step 0 or a `newScene` step. */
export function scenesOf(project: Project): SceneInfo[] {
  const scenes: SceneInfo[] = [];
  project.steps.forEach((step, i) => {
    if (i === 0 || step.newScene) scenes.push({ index: scenes.length, first: i, last: i, name: step.sceneName });
    else scenes[scenes.length - 1].last = i;
  });
  return scenes;
}

/** The scene that contains `step`. */
export function sceneOf(project: Project, step: number): SceneInfo {
  const scenes = scenesOf(project);
  return scenes.find((s) => step >= s.first && step <= s.last) ?? scenes[scenes.length - 1];
}

/** Index of the step that starts the scene containing `step`. */
export function sceneStart(project: Project, step: number): number {
  let i = Math.min(step, project.steps.length - 1);
  while (i > 0 && !project.steps[i].newScene) i--;
  return Math.max(0, i);
}

/** Ink colors tuned for the off-white background: ink, pencil gray, then accents. */
export const PALETTE = ['#1e1e1e', '#868e96', '#f59f00', '#1c7ed6', '#e03131', '#2f9e44'] as const;
export const SIZES = { thin: 4, medium: 7, bold: 12 } as const;
export const DEFAULT_HOLD = 400;

export function uid(): string {
  return Math.random().toString(36).slice(2, 10);
}

export function createStep(init: Partial<Omit<Step, 'id'>> = {}): Step {
  return { id: uid(), strokes: [], hold: DEFAULT_HOLD, ...init };
}

export function createProject(init: Partial<Omit<Project, 'version' | 'steps'>> = {}): Project {
  return {
    version: 1,
    width: 1920,
    height: 1080,
    background: '#f8f9fa',
    speed: 1,
    ...init,
    steps: [createStep()],
  };
}

/** Light validation for files coming from disk or another program. */
export function parseProject(data: unknown): Project {
  const p = data as Partial<Project> | null;
  if (!p || p.version !== 1 || !Array.isArray(p.steps) || p.steps.length === 0) {
    throw new Error('Not a Retrace project (expected version 1 with at least one step)');
  }
  for (const step of p.steps) {
    if (!Array.isArray(step.strokes)) throw new Error(`Step ${step.id} has no strokes array`);
  }
  if (p.tracks !== undefined && (!Array.isArray(p.tracks) || p.tracks.some((t) => typeof t?.id !== 'string'))) {
    throw new Error('Tracks must be a list of { id, name }');
  }
  return {
    ...createProject(),
    ...p,
    speed: typeof p.speed === 'number' && p.speed > 0 ? p.speed : 1,
  } as Project;
}

export function strokeDuration(stroke: Stroke): number {
  return stroke.points.length ? stroke.points[stroke.points.length - 1][3] : 0;
}
